const fs = require('fs');
const vm = require('vm');
const path = require('path');

const build = process.argv[2];
const html = fs.readFileSync(path.join(build, 'index.html'), 'utf8');
const refs = [...html.matchAll(/(?:src|href)=["']([^"']+)["']/g)].map(m => m[1]).filter(r => !/^(?:https?:|data:|#)/.test(r));
for (const ref of refs) {
  const p = path.join(build, ref);
  if (!fs.existsSync(p)) throw new Error(`missing ref ${ref}`);
  console.log(`REF ${ref} exists sha256=${require('crypto').createHash('sha256').update(fs.readFileSync(p)).digest('hex')}`);
}

class Classes { constructor(){this.s=new Set()} toggle(n,on){on?this.s.add(n):this.s.delete(n)} contains(n){return this.s.has(n)} }
class El { constructor(){this.textContent='';this.style={};this.hidden=true;this.classList=new Classes();this.attrs={};this.parentElement=null} setAttribute(k,v){this.attrs[k]=v} }
const els = Object.fromEntries(['shells','tide','tide-status','tide-bar','result','hud','tide-track'].map(x=>[x,new El()]));
els['tide-bar'].parentElement=els['tide-track'];
const ctx2d={clearRect(){},fillRect(){},beginPath(){},arc(){},fill(){},fillStyle:''};
els.game={width:480,height:320,getContext(){return ctx2d}};
const queue=[]; const listeners={}; let now=0;
const sandbox={console,Math,clearInterval,performance:{now:()=>now},requestAnimationFrame:cb=>queue.push(cb),document:{getElementById:id=>els[id]},window:{addEventListener:(n,cb)=>listeners[n]=cb}};
vm.createContext(sandbox);
vm.runInContext(fs.readFileSync(path.join(build,'main.js'),'utf8')+'\n;globalThis.__state=()=>({remainingSeconds,roundState,shellCount,shells:shells.length,player:{...player},recoveries:activeRecoveries.length}); globalThis.__settle=settleRound;',sandbox,{filename:'main.js'});
const snap=label=>console.log(label,JSON.stringify({state:sandbox.__state(),tide:els.tide.textContent,width:els['tide-bar'].style.width,aria:els['tide-track'].attrs['aria-valuenow'],urgent:els['tide-status'].classList.contains('urgent'),status:els['tide-status'].textContent,resultHidden:els.result.hidden,result:els.result.textContent}));
const step=()=>{now+=50; const cb=queue.shift(); if(!cb) throw new Error('no animation frame'); cb(now)};
snap('INIT');
step(); snap('DECREMENT');
for(let i=1;i<1000;i++) step(); snap('AT_10_SECONDS');
step(); snap('BELOW_10_SECONDS');
for(let i=0;i<1000;i++) step(); snap('SETTLED');
const before=JSON.stringify(sandbox.__state());
listeners.keydown({key:'ArrowRight'}); for(let i=0;i<2;i++) step(); sandbox.__settle();
const after=JSON.stringify(sandbox.__state()); snap('POST_SETTLE_2_FRAMES_AND_REPEAT');
if(before!==after) throw new Error(`settled state changed before=${before} after=${after}`);
console.log('PASS settlement idempotent and game state frozen');

